import { useEffect, useRef, useState } from 'react';
import { Navigate, NavLink, Route, Routes, useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { LayoutDashboard, BookOpen, Mic2, ChartNoAxesColumnIncreasing, Search, Bell, Plus, ArrowUpRight, Clock3, Play, ChevronRight, ChevronLeft, Sparkles, FileText, Check, X, Menu, CircleHelp, MoveUpRight, Send, RotateCcw, Brain, Target, Sun, Moon, LogOut, Settings as SettingsIcon, Languages, Mic, Volume2, UserRound, GraduationCap } from 'lucide-react';

const api = axios.create({ baseURL: import.meta.env.VITE_API_URL || '/api', withCredentials: true });
const demoStops=[
 {path:'/',title:'1 · Dashboard',copy:'Review the personalized dashboard. These saved records are labelled sample data. The demo account is separate from real student accounts.'},
 {path:'/learn',title:'2 · Technical learning',copy:'Open the JavaScript Event Loop demo guide, ask a follow-up question, and finalize the session.'},
 {path:'/interview',title:'3 · Mock interview',copy:'Choose a topic and difficulty. Try typed answers or voice practice, replay a question, and use Previous question.'},
 {path:'/progress',title:'4 · Progress',copy:'Review the saved sample interview report, scores, and revision topics.'},
 {path:'/settings',title:'5 · Settings and theme',copy:'Switch light/dark theme, review demo profile settings, then use Exit demo to sign out.'},
];
function Shell({ children, user, onLogout }) {
  const [menu,setMenu]=useState(false);
  const [theme,setTheme]=useState(()=>localStorage.getItem('prepai-theme')==='light'?'light':'dark');
  const [showSearch,setShowSearch]=useState(false);
  const [searchQuery,setSearchQuery]=useState('');
  const [showNotifications,setShowNotifications]=useState(false);
  const [profileMenu,setProfileMenu]=useState(false);
  const [accountMenu,setAccountMenu]=useState(false);
  const [helpOpen,setHelpOpen]=useState(false);
  const navigate=useNavigate(); const location=useLocation(); const activeDemoIndex=demoStops.findIndex(step=>step.path===location.pathname); const demoStep=activeDemoIndex>=0?activeDemoIndex:0; const demoStop=demoStops[demoStep];
  function nextDemoStop(){const next=demoStep+1;if(next>=demoStops.length){onLogout();return;}navigate(demoStops[next].path);}
  const searchPages=[{to:'/',label:'Overview',detail:'Dashboard and recent activity'},{to:'/learn',label:'Technical learning',detail:'Open a local topic guide'},{to:'/interview',label:'Mock interview',detail:'Practice role-based questions'},{to:'/progress',label:'My progress',detail:'Review sessions and weak topics'},{to:'/settings',label:'Settings',detail:'Language and account preferences'}];
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('prepai-theme',theme);},[theme]);
  useEffect(()=>{function onKeyDown(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();setShowSearch(true);setShowNotifications(false);}if(event.key==='Escape'){setShowSearch(false);setShowNotifications(false);}}window.addEventListener('keydown',onKeyDown);return()=>window.removeEventListener('keydown',onKeyDown);},[]);
  return <div className="app-shell" data-theme={theme}><aside className={menu?'sidebar open':'sidebar'}>
    <div className="brand"><div className="brand-mark"><span>p</span></div><span>prepai<span className="brand-dot">.</span></span></div>
    <div className="workspace-label">WORKSPACE</div>
    <nav className="nav-list">
      <NavLink to="/" end onClick={()=>setMenu(false)}><LayoutDashboard size={17}/>Overview</NavLink>
      <NavLink to="/learn" onClick={()=>setMenu(false)}><BookOpen size={17}/>Technical learning</NavLink>
      <NavLink to="/interview" onClick={()=>setMenu(false)}><Mic2 size={17}/>Mock interview</NavLink>
      <NavLink to="/progress" onClick={()=>setMenu(false)}><ChartNoAxesColumnIncreasing size={17}/>My progress</NavLink>
    </nav>
    <div className="sidebar-bottom"><button className="help-card" onClick={()=>setHelpOpen(true)}><div className="help-icon"><CircleHelp size={16}/></div><div><b>Need a hand?</b><span>Open the help guide</span></div><MoveUpRight size={14}/></button><div className="profile-wrap"><button className="profile" onClick={()=>setProfileMenu(!profileMenu)} aria-expanded={profileMenu}><div className="avatar">{user.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()}</div><div className="profile-copy"><b>{user.name}</b><span>{user.email}</span></div><span className="profile-more">•••</span></button>{profileMenu&&<div className="profile-menu"><button onClick={()=>{navigate('/settings');setProfileMenu(false);}}><SettingsIcon size={14}/> Settings</button><button onClick={onLogout}><LogOut size={14}/> Sign out</button></div>}</div></div>
  </aside><main className="main-area">{user.demoMode&&<section className="demo-banner" role="status"><div><span>DEMO MODE · SAMPLE DATA · STEP {demoStep+1} / {demoStops.length}</span><b>{demoStop.title}</b><p>{demoStop.copy}</p><small>Shared demo account. Do not enter personal information.</small></div><button className="button" type="button" onClick={nextDemoStop}>{demoStep===demoStops.length-1?'Exit demo':'Next demo step'} <ChevronRight size={14}/></button><button className="quiet-action" type="button" onClick={onLogout}>Sign out</button></section>}<header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setMenu(!menu)} aria-label="Toggle navigation"><Menu size={18}/></button><div className="crumb">Workspace <ChevronRight size={13}/> <span>Interview prep</span></div><div className="top-actions"><button className="search-control" onClick={()=>{setShowSearch(true);setShowNotifications(false);}} aria-label="Search workspace"><Search size={15}/><span>Search</span><kbd>Ctrl K</kbd></button><button className="icon-button theme-toggle" onClick={()=>setTheme(theme==='dark'?'light':'dark')} aria-label={theme==='dark'?'Switch to light theme':'Switch to dark theme'} title={theme==='dark'?'Switch to light theme':'Switch to dark theme'}>{theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}</button><div className="notification-wrap"><button className="icon-button notify" onClick={()=>setShowNotifications(!showNotifications)} aria-label="Notifications" aria-expanded={showNotifications}><Bell size={17}/><i/></button>{showNotifications&&<div className="notification-popover" role="status"><b>You’re all caught up</b><span>New learning and interview activity will appear here.</span></div>}</div><button className="avatar small account-avatar" onClick={()=>setAccountMenu(!accountMenu)} aria-label="Account menu" aria-expanded={accountMenu}>{user.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()}</button></div></header>{children}</main>{showSearch&&<div className="search-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setShowSearch(false);}}><section className="search-dialog" role="dialog" aria-modal="true" aria-label="Search workspace"><div className="search-dialog-input"><Search size={17}/><input autoFocus value={searchQuery} onChange={event=>setSearchQuery(event.target.value)} placeholder="Search pages and actions…" aria-label="Search pages and actions"/><button className="icon-button" onClick={()=>setShowSearch(false)} aria-label="Close search"><X size={17}/></button></div><div className="search-results">{searchPages.filter(page=>(page.label+' '+page.detail).toLowerCase().includes(searchQuery.toLowerCase())).map(page=><button key={page.to} onClick={()=>{navigate(page.to);setShowSearch(false);setSearchQuery('');}}><span><b>{page.label}</b><small>{page.detail}</small></span><ArrowUpRight size={15}/></button>)}{!searchPages.some(page=>(page.label+' '+page.detail).toLowerCase().includes(searchQuery.toLowerCase()))&&<p>No matching pages. Try “learning” or “progress”.</p>}</div></section></div>}{accountMenu&&<div className="account-popover"><button onClick={()=>{navigate('/settings');setAccountMenu(false);}}><SettingsIcon size={14}/> Settings</button><button onClick={onLogout}><LogOut size={14}/> Sign out</button></div>}{helpOpen&&<div className="search-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setHelpOpen(false);}}><section className="search-dialog help-dialog" role="dialog" aria-modal="true" aria-label="PrepAI help"><div className="panel-heading"><div><h2><CircleHelp size={16}/> PrepAI quick guide</h2><p>Choose a workspace area to continue.</p></div><button className="icon-button" onClick={()=>setHelpOpen(false)} aria-label="Close help"><X size={17}/></button></div>{searchPages.map(page=><button className="help-link" key={page.to} onClick={()=>{navigate(page.to);setHelpOpen(false);}}><span><b>{page.label}</b><small>{page.detail}</small></span><ArrowUpRight size={15}/></button>)}</section></div>}</div>
}
function PageHeader({eyebrow,title,subtitle,action}) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>; }
function Button({children,onClick,secondary=false,disabled=false}) { return <button disabled={disabled} onClick={onClick} className={secondary?'button secondary':'button'}>{children}</button>; }
function Stat({label,value,delta,icon:Icon,accent}) { return <div className="stat-card"><div className="stat-top"><span>{label}</span><span className={'stat-icon '+(accent||'')}><Icon size={16}/></span></div><div className="stat-number">{value}</div><div className="stat-foot"><span className="delta">{delta}</span></div></div>; }
function Dashboard({ user }) {
 const [data,setData]=useState({learnings:[],interviews:[],learningCount:0,completedSessions:0,strongTopics:[],weakTopics:[],averageScore:null,recommendation:''}); const [error,setError]=useState('');
 useEffect(()=>{api.get('/dashboard').then(r=>setData(r.data)).catch(()=>setError('Could not load your dashboard. Check that the API is running.'));},[]);
 const navigate=useNavigate(); const sessions=data.interviews; const name=(user.name||'there').trim().split(/\s+/)[0];
 return <div className="page-content">
  <div className="welcome-strip"><div><div className="eyebrow">{new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'2-digit'}).toUpperCase()}</div><h1>Hi, {name}<span>!</span></h1><p>Your preparation, picked up right where you left off.</p></div><div className="welcome-mark">✳</div></div>
  {error&&<div className="error-banner">{error}</div>}
  <div className="section-heading"><div><h2>Your overview</h2><span>Progress from your saved practice</span></div><button className="text-link" onClick={()=>navigate('/progress')}>View progress <ArrowUpRight size={14}/></button></div>
  <div className="stats-grid"><Stat label="Learning progress" value={data.learningCount} delta="Study packs completed" icon={BookOpen}/><Stat label="Completed interviews" value={data.completedSessions} delta="Saved evaluation reports" icon={Mic2} accent="mint"/><Stat label="Average interview score" value={data.averageScore==null?'—':data.averageScore+'%'} delta="Across your completed sessions" icon={Target} accent="purple"/><Stat label="Latest activity" value={sessions[0]||data.learnings[0]?'Active':'Start'} delta={sessions[0]||data.learnings[0]?'Your workspace is up to date':'Build your first study pack'} icon={Sparkles} accent="gold"/></div>
  <div className="dashboard-columns"><section className="panel recent-panel"><div className="panel-heading"><div><h2>Recent activity</h2><p>Your latest learning and practice</p></div><button className="text-link" onClick={()=>navigate('/progress')}>View all <ArrowUpRight size={14}/></button></div>
   <div className="activity-list">{[...data.learnings.map(x=>({...x,kind:'Learning'})),...sessions.map(x=>({...x,kind:'Interview'}))].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5).map((x,i)=><div className="activity-row" key={x._id||i}><div className={'activity-icon '+(x.kind==='Interview'?'violet':'cyan')}>{x.kind==='Interview'?<Mic2 size={16}/>:<Play size={16}/>}</div><div className="activity-name"><b>{x.kind==='Interview'?x.role:x.title}</b><span>{x.kind} · {new Date(x.createdAt).toLocaleDateString()}</span></div><div className="activity-meta">{x.kind==='Interview'?(x.report?x.report.overallScore+'% score':'In progress'):'Study pack'}<ChevronRight size={14}/></div></div>)}
   {!data.learnings.length&&!sessions.length&&<div className="empty-state"><div className="empty-glyph"><Sparkles size={22}/></div><b>Your next breakthrough starts here</b><span>Your study packs and interview reports will show up here.</span><Button onClick={()=>navigate('/learn')}><Plus size={15}/> Start learning</Button></div>}
  </div></section><section className="panel actions-panel"><div className="panel-heading"><div><h2>Focus for next time</h2><p>Based on your interview results</p></div></div><div className="dashboard-topic-group"><span className="field-label">STRONGEST AREAS</span>{data.strongTopics.length?data.strongTopics.map(item=><div className="topic-row" key={item.topic}><span>{item.topic}</span><b>{item.score}%</b></div>):<div className="empty-compact">Complete an interview to identify your strongest areas.</div>}</div><div className="dashboard-topic-group"><span className="field-label">TOPICS TO REVISIT</span>{data.weakTopics.length?data.weakTopics.map(item=><div className="topic-row" key={item.topic}><span>{item.topic}</span><b>{item.count}×</b></div>):<div className="empty-compact">Your recommendations will be based on saved reports.</div>}</div><button className="recommendation-card" onClick={()=>navigate('/learn')}><span className="action-icon blue"><BookOpen size={17}/></span><span><small>RECOMMENDED LEARNING</small><b>{data.recommendation||'Create your first topic guide'}</b></span><ArrowUpRight size={15}/></button><button className="action-card" onClick={()=>navigate('/interview')}><span className="action-icon lavender"><Mic2 size={17}/></span><span><b>Practice an interview</b><small>Build confidence one answer at a time</small></span><ArrowUpRight size={16}/></button></section></div>
 </div>
}
function Learn() {
 const [title,setTitle]=useState(''); const [transcript,setTranscript]=useState(''); const [sourceType,setSourceType]=useState('topic'); const [youtubeUrl,setYoutubeUrl]=useState(''); const [file,setFile]=useState(null); const [result,setResult]=useState(null); const [busy,setBusy]=useState(false); const [status,setStatus]=useState(''); const [error,setError]=useState(''); const [revealed,setRevealed]=useState({}); const [chatQuestion,setChatQuestion]=useState(''); const [chatMessages,setChatMessages]=useState([]); const [chatBusy,setChatBusy]=useState(false);
 const [videoLanguage,setVideoLanguage]=useState('Auto Detect'); const [explanationLanguage,setExplanationLanguage]=useState('English'); const [learningAction,setLearningAction]=useState(null); const [learningActionBusy,setLearningActionBusy]=useState(false); const [quizIndex,setQuizIndex]=useState(0); const [quizAnswer,setQuizAnswer]=useState(''); const [quizFeedback,setQuizFeedback]=useState(''); const [quizBusy,setQuizBusy]=useState(false);
 const [localServices,setLocalServices]=useState(null); const [whisperLanguages,setWhisperLanguages]=useState([{name:'English',code:'en'}]); const [checkingServices,setCheckingServices]=useState(false);
 const [savedSessions,setSavedSessions]=useState([]); const [selectedSession,setSelectedSession]=useState(''); const [finalizeBusy,setFinalizeBusy]=useState(false); const location=useLocation();
 async function checkLocalServices(){setCheckingServices(true);try{const response=await api.get('/learning/services',{timeout:10000});setLocalServices(response.data.services);if(Array.isArray(response.data.languages)&&response.data.languages.length){setWhisperLanguages(response.data.languages);}}catch(err){setError(err.response?.data?.error||'Could not check local video services.');}finally{setCheckingServices(false);}}
 async function refreshSavedSessions(){try{const response=await api.get('/learning');setSavedSessions(response.data.sessions||[]);}catch(err){setError(err.response?.data?.error||'Could not load your saved study sessions.');}}
 useEffect(()=>{refreshSavedSessions();const id=new URLSearchParams(location.search).get('session');if(id)openSavedSession(id);},[location.search]);
 useEffect(()=>{checkLocalServices();},[]);
 async function openSavedSession(id){if(!id)return;setError('');try{const response=await api.get('/learning/'+id);const session=response.data;setResult(session);setTitle(session.title||'');setTranscript(session.transcript||'');setSourceType(session.sourceType||'topic');setYoutubeUrl(session.sourceUrl||'');setVideoLanguage(session.videoLanguage||session.sourceLanguage||'Auto Detect');setExplanationLanguage(session.explanationLanguage||session.outputLanguage||'English');setChatMessages(session.chatHistory||[]);setSelectedSession(id);setRevealed({});setLearningAction(null);}catch(err){setError(err.response?.data?.error||'Could not open the saved study session.');}}
 async function finalizeSession(){if(!result?._id||finalizeBusy)return;setFinalizeBusy(true);setError('');try{const response=await api.post('/learning/'+result._id+'/finalize');setResult(response.data.session);setSelectedSession(result._id);await refreshSavedSessions();}catch(err){setError(err.response?.data?.error||'Could not finalize the study session.');}finally{setFinalizeBusy(false);}}
 async function submit(event){event.preventDefault();setError('');setStatus('');if(!title.trim()&&sourceType!=='youtube'&&!file){setError('Enter a session title or choose a video file.');return;}if(sourceType==='transcript'&&transcript.trim().length<30){setError('Paste at least 30 characters of transcript or captions.');return;}if(sourceType==='youtube'&&!youtubeUrl.trim()){setError('Add a YouTube video link.');return;}if(sourceType==='upload'&&!file){setError('Choose an audio or video file first.');return;}setBusy(true);try{if(sourceType==='topic'&&!transcript.trim()){setStatus('Building your local topic guide…');const response=await api.post('/learning',{title,sourceType:'topic'});setResult(response.data);setSelectedSession(response.data._id);setChatMessages(response.data.chatHistory||[]);}else{const payload={sourceType:sourceType==='topic'?'transcript':sourceType,title,transcript,youtubeUrl,videoLanguage,explanationLanguage};setStatus(file?'Uploading media to the local processor…':'Starting local transcript processing…');const started=file?await api.post('/learning/process',file,{timeout:0,headers:{'Content-Type':file.type||'application/octet-stream','X-PrepAI-Source':'upload','X-PrepAI-Title':encodeURIComponent(title),'X-PrepAI-Name':encodeURIComponent(file.name),'X-PrepAI-Mime':file.type||'','X-PrepAI-Video-Language':videoLanguage,'X-PrepAI-Explanation-Language':explanationLanguage}}):await api.post('/learning/process',payload,{timeout:0});let job;do{await new Promise(resolve=>setTimeout(resolve,1200));const poll=await api.get('/learning/jobs/'+started.data.jobId,{timeout:0});job=poll.data;setStatus((job.message||'Processing locally…')+(job.progress!=null?' · '+job.progress+'%':''));}while(job.status==='processing');if(job.status!=='complete'||!job.session)throw new Error(job.error||'Local processing did not complete; no study pack was saved.');setResult(job.session);setSelectedSession(job.session._id);setChatMessages(job.session.chatHistory||[]);}setChatQuestion('');setLearningAction(null);setQuizIndex(0);setQuizFeedback('');setRevealed({});setFile(null);await refreshSavedSessions();}catch(err){setError(err.response?.data?.error||err.message||'Could not create the study pack. Check local services and try again.');}finally{setBusy(false);setStatus('');}}
async function runLearningAction(action){if(!result?._id||learningActionBusy)return;setLearningActionBusy(true);setError('');setLearningAction(null);try{const response=await api.post('/learning/'+result._id+'/action',{action},{timeout:0});setLearningAction({...response.data,action});setQuizIndex(0);setQuizAnswer('');setQuizFeedback('');}catch(err){setError(err.response?.data?.error||'The local learning assistant could not complete this request.');}finally{setLearningActionBusy(false);}}
async function checkQuizAnswer(event){event.preventDefault();if(!learningAction?.quiz?.[quizIndex]||!quizAnswer.trim()||quizBusy)return;const item=learningAction.quiz[quizIndex];const answerIndex=Number(item.answerIndex??item.answer??0);const expectedAnswer=item.options?.[answerIndex]||String(item.answer||'');setQuizBusy(true);setError('');try{const response=await api.post('/learning/'+result._id+'/quiz-answer',{question:item.question,expectedAnswer,answer:quizAnswer},{timeout:0});setQuizFeedback(response.data.feedback||response.data.explanation||'Answer checked against the transcript.');}catch(err){setError(err.response?.data?.error||'Could not check this quiz answer.');}finally{setQuizBusy(false);}}
function nextQuizQuestion(){setQuizIndex(value=>value+1);setQuizAnswer('');setQuizFeedback('');}
async function askAboutSource(event){event.preventDefault();const question=chatQuestion.trim();if(!result?._id||question.length<3||chatBusy)return;setChatBusy(true);setError('');setChatMessages(previous=>[...previous,{question,answer:'',pending:true}]);setChatQuestion('');try{const response=await api.post('/learning/'+result._id+'/ask',{question},{timeout:120000});setChatMessages(previous=>previous.map((item,index)=>index===previous.length-1?{...item,answer:response.data.answer,mode:response.data.mode,pending:false}:item));setResult(previous=>({...previous,chatHistory:[...(previous.chatHistory||[]),{question,answer:response.data.answer,mode:response.data.mode}]}));}catch(err){setChatMessages(previous=>previous.slice(0,-1));setError(err.response?.data?.error||'Could not answer from this study source.');setChatQuestion(question);}finally{setChatBusy(false);}}
 
 return <div className="page-content"><PageHeader eyebrow="TECHNICAL TOPIC LEARNING" title="Learn with intention." subtitle="Choose a technical topic and build a study guide you can save and revisit."/><div className="saved-session-picker"><label className="field-label" htmlFor="saved-session">CONTINUE A SAVED SESSION</label><select id="saved-session" className="text-input" value={selectedSession} onChange={event=>openSavedSession(event.target.value)}><option value="">Choose a saved topic guide…</option>{savedSessions.map(item=><option key={item._id} value={item._id}>{item.title}{item.finalizedAt?' · Finalized':' · In progress'}</option>)}</select></div><div className="learning-layout"><form className="panel input-panel" onSubmit={submit}><div className="panel-heading"><div><h2><span className="step-index">01</span> Choose your topic</h2><p>Choose a technical topic, or add transcript text for answers grounded in your source.</p></div></div><label className="field-label" htmlFor="learning-source">SOURCE TYPE</label><select id="learning-source" className="text-input source-select" value={sourceType} onChange={event=>{setSourceType(event.target.value);setFile(null);setError('');}}><option value="topic">Technical topic guide (offline)</option><option value="transcript">Paste transcript</option><option value="youtube">Public YouTube video</option><option value="upload">Upload audio or video</option></select>{sourceType==='youtube'&&<><label className="field-label" htmlFor="youtube-url">YOUTUBE LINK</label><input id="youtube-url" className="text-input" type="url" value={youtubeUrl} onChange={event=>setYoutubeUrl(event.target.value)} placeholder="https://www.youtube.com/watch?v=…"/>{youtubeUrl.match(/(?:v=|youtu\.be\/)([\w-]{11})/)?.[1]&&<div className="youtube-preview"><iframe title="YouTube video preview" src={`https://www.youtube-nocookie.com/embed/${youtubeUrl.match(/(?:v=|youtu\.be\/)([\w-]{11})/)[1]}`} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen/></div>}</>}{sourceType==='upload'&&<><label className="field-label" htmlFor="media-file">AUDIO OR VIDEO FILE</label><input id="media-file" className="text-input file-input" type="file" accept="audio/*,video/mp4,video/mpeg,video/quicktime,video/webm,video/x-msvideo,video/x-matroska" onChange={event=>setFile(event.target.files?.[0]||null)}/><small className="form-hint">The media is uploaded to your local PrepAI server for private transcription and analysis.</small></>}<label className="field-label" htmlFor="video-language">VIDEO LANGUAGE</label><select id="video-language" className="text-input source-select" value={videoLanguage} onChange={event=>setVideoLanguage(event.target.value)}><option>Auto Detect</option>{whisperLanguages.map(language=><option key={language.code} value={language.name}>{language.name}</option>)}</select><label className="field-label" htmlFor="explanation-language">EXPLANATION LANGUAGE</label><select id="explanation-language" className="text-input source-select" value={explanationLanguage} onChange={event=>setExplanationLanguage(event.target.value)}>{whisperLanguages.map(language=><option key={language.code} value={language.name}>{language.name}</option>)}</select><small className="form-hint">The original transcript is preserved. Video and transcript processing uses the selected explanation language; offline topic guides stay in English.</small><label className="field-label" htmlFor="session-title">TECHNICAL TOPIC OR SESSION TITLE</label><input id="session-title" className="text-input" value={title} onChange={event=>setTitle(event.target.value)} placeholder="e.g. HTML, Java, or React" maxLength={100} required/><label className="field-label" htmlFor="transcript-input">{sourceType==='youtube'?'CAPTIONS OR TRANSCRIPT (OPTIONAL)':sourceType==='topic'?'OPTIONAL SOURCE TRANSCRIPT':'VIDEO TRANSCRIPT'} <span>{transcript.length.toLocaleString()} / 500,000</span></label><textarea id="transcript-input" className="transcript-input" value={transcript} onChange={event=>setTranscript(event.target.value.slice(0,18000))} placeholder={sourceType==='youtube'?'Paste captions for source-based notes. Without captions, PrepAI creates a title-based guide only.':'Paste a transcript here…'} required={sourceType==='transcript'}/><small className="form-hint">Transcript notes stay in their original language. Built-in topic guides are available in English.</small><div className="form-foot"><span><FileText size={13}/>{sourceType==='upload'?'Media is processed locally in 10-minute audio chunks':'Transcript and captions work best under 18,000 characters'}</span><Button disabled={busy}>{busy?<><span className="spinner"/> {status||'Working…'}</>:<><Sparkles size={15}/> Create study pack</>}</Button></div>{error&&<div className="error-banner" role="alert">{error}</div>}</form><aside className="learning-aside"><div className="aside-note"><div className="aside-note-icon"><Brain size={17}/></div><h3>A better way to review</h3><p>PrepAI includes built-in English guides for common development topics. Add a transcript for source-grounded notes.</p></div><div className="aside-list local-service-card"><div className="panel-heading"><b>LOCAL VIDEO SERVICES</b><button type="button" className="quiet-action" onClick={checkLocalServices} disabled={checkingServices}>{checkingServices?'Checking…':'Check again'}</button></div>{localServices?Object.entries(localServices).map(([name,service])=>{const ok=service.available&&(!['ollama','whisper'].includes(name)||service.modelInstalled);return <span key={name} className={ok?'service-ok':'service-missing'}><i/>{service.label||name}{name==='ollama'&&service.model?': '+service.model:''} · {ok?'Ready':'Unavailable'}{!ok&&<small>{service.error||(name==='ollama'?'Run ollama pull '+(service.model||'llama3.2'):'Install the tool and ensure it is on PATH.')}</small>}</span>}):<span>Checking Java video processing, whisper.cpp, FFmpeg, yt-dlp, and Ollama…</span>}</div><div className="aside-list"><b>YOUR STUDY PACK INCLUDES</b>{['A concise summary','Key concepts to remember','Questions to check understanding','Quick quiz & flashcards'].map(item=><span key={item}><Check size={14}/>{item}</span>)}</div></aside></div>{result&&<section className="panel results-panel"><div className="results-heading"><div><div className="eyebrow">YOUR STUDY PACK</div><h2>{result.title}</h2><p className="language-meta"><Languages size={13}/> Detected: {result.sourceLanguage||'Unknown'} · Notes: {result.outputLanguage||'English'}</p></div><span className="saved-badge"><Check size={13}/> Saved</span></div>{result.fallbackLabel&&<div className="fallback-banner" role="note"><b>{result.fallbackLabel}</b>{result.titlePracticeLabel&&<span>{result.titlePracticeLabel}</span>}</div>}{status&&<p className="status-note" role="status">{status}</p>}{error&&<div className="error-banner" role="alert">{error}</div>}<div className="result-section"><h3>Explanation</h3><p>{result.explanation||result.summary}</p></div>{(result.notes?.length||result.keyPoints?.length)>0&&<div className="result-section"><h3>Structured notes</h3><ul className="key-list">{(result.notes?.length?result.notes:(result.keyPoints||[])).map((item,index)=><li key={index}>{item}</li>)}</ul></div>}<div className="result-section"><h3>In a nutshell</h3><p>{result.summary}</p></div>{result.keyPoints?.length>0&&<div className="result-section"><h3>Key concepts</h3><ul className="key-list">{result.keyPoints.map((item,index)=><li key={index}>{item}</li>)}</ul></div>}{result.revisionPoints?.length>0&&<div className="result-section"><h3>Revision points</h3><ul className="key-list">{result.revisionPoints.map((item,index)=><li key={index}>{item}</li>)}</ul></div>}{result.whatToLearnNext?.length>0&&<div className="result-section"><h3>What should I learn from this topic?</h3><ul className="key-list">{result.whatToLearnNext.map((item,index)=><li key={index}>{item}</li>)}</ul></div>}{result.examples?.length>0&&<div className="result-section"><h3>Examples</h3>{result.examples.map((example,index)=><div className="topic-example" key={index}><b>{example.title}</b><pre><code>{example.code}</code></pre><p>{example.explanation}</p></div>)}</div>}<div className="result-section"><h3>Questions &amp; answers</h3>{result.questions.map((question,index)=><div className="question-line" key={index}><span>0{index+1}</span><div><b>{question}</b><p>{result.answers?.[index]||'Review the source transcript for this answer.'}</p></div></div>)}</div>{result.generationMode==='local-whisper-ollama'&&<div className="result-section"><h3>Learn more from this video</h3><div className="learning-options" role="group" aria-label="Video learning options">{[['explain','Explain This Topic Again'],['practice','Generate Practice Questions'],['quiz','Quiz Me'],['examples','Give More Examples'],['next','What Should I Learn Next?']].map(([action,label])=><button type="button" className="button secondary" key={action} disabled={learningActionBusy} onClick={()=>runLearningAction(action)}>{label}</button>)}</div>{learningActionBusy&&<p role="status" className="status-note"><span className="spinner"/> Preparing a transcript-grounded response with the local model…</p>}{learningAction&&learningAction.action!=='quiz'&&<div className="learning-action-result" aria-live="polite">{(learningAction.text||learningAction.explanation)&&<p>{learningAction.text||learningAction.explanation}</p>}{(learningAction.questions||[]).map((question,index)=><div className="question-line" key={index}><b>{question}</b><p>{learningAction.answers?.[index]||''}</p></div>)}{(learningAction.examples||[]).map((example,index)=><div className="topic-example" key={index}><b>{example.title||'Example'}</b><pre><code>{example.code||''}</code></pre><p>{example.explanation||example.sourceReference||''}</p></div>)}{(learningAction.recommendations||learningAction.whatToLearnNext||[]).map((item,index)=><p key={index}>{item}</p>)}{learningAction.sourceReferences?.length>0&&<small>Transcript references: {learningAction.sourceReferences.join(' · ')}</small>}</div>}{learningAction?.action==='quiz'&&(()=>{const item=learningAction.quiz?.[quizIndex];return item?<form className="video-quiz" onSubmit={checkQuizAnswer}><b>Question {quizIndex+1} of {learningAction.quiz.length}</b><p>{item.question}</p>{item.options?.length?<div className="quiz-options">{item.options.map((option,index)=><label key={index}><input type="radio" name="video-quiz-answer" value={option} checked={quizAnswer===option} onChange={()=>setQuizAnswer(option)}/>{option}</label>)}</div>:<textarea className="answer-input" value={quizAnswer} onChange={event=>setQuizAnswer(event.target.value)} required/>}{quizFeedback?<><p role="status">{quizFeedback}</p><button type="button" className="button" onClick={nextQuizQuestion}>{quizIndex+1<learningAction.quiz.length?'Next quiz question':'Finish quiz'}</button></>:<button className="button" disabled={!quizAnswer||quizBusy}>{quizBusy?'Checking…':'Check answer'}</button>}</form>:<p role="status">Quiz complete.</p>;})()}</div>}{result.importantTimestamps?.length>0&&<div className="result-section"><h3>Important timestamps</h3>{result.importantTimestamps.map((item,index)=><p className="report-item" key={index}><b>{item.timestamp||item.time||''}</b> {item.point||item.text||String(item)}</p>)}</div>}{result.generationMode==='local-whisper-ollama'&&<details className="result-section original-transcript"><summary>View original transcript · {result.sourceLanguage}</summary><pre>{result.transcript}</pre></details>}<div className="result-section video-chat"><h3>{result.generationMode==='local-whisper-ollama'?'Ask a Question':'Ask about this session'}</h3><p>{result.generationMode==='local-whisper-ollama'?'Answers use local Ollama with the saved original transcript and include transcript references where available. Unsupported questions are declined.':result.transcript?.trim()?'Answers use the saved transcript and quote matching source text. Unsupported questions are declined.':'This built-in topic guide is not a video summary. Answers use its listed concepts and examples; questions outside those notes are identified.'}</p><div className="video-chat-messages">{chatMessages.map((item,index)=><div className="video-chat-turn" key={index}><b>You</b><p>{item.question}</p><b>PrepAI</b>{item.mode==='local-topic-guide'&&<span className="fallback-inline">Built-in topic reference</span>}<p>{item.pending?'Checking the saved session…':item.answer}</p></div>)}</div><form className="video-chat-form" onSubmit={askAboutSource}><input className="text-input" value={chatQuestion} onChange={event=>setChatQuestion(event.target.value)} maxLength={1000} minLength={3} placeholder="Ask a question grounded in this content…" required/><button className="button" disabled={chatBusy}>{chatBusy?<><span className="spinner"/> Searching…</>:<>Ask <Send size={14}/></>}</button></form><div className="session-finalize-row">{result.finalizedAt?<span className="saved-message" role="status">Session finalized and saved to progress.</span>:<button className="button secondary" type="button" onClick={finalizeSession} disabled={finalizeBusy}>{finalizeBusy?'Saving…':'Finalize & save progress'}</button>}</div></div>{result.quiz?.length>0&&<div className="result-section"><h3>Quick quiz</h3>{result.quiz.map((quiz,index)=><div className="quiz-card" key={index}><b>{quiz.question}</b><div className="quiz-options">{quiz.options.map((option,optionIndex)=><label key={optionIndex}><input type="radio" name={'quiz'+index} value={optionIndex}/>{option}</label>)}</div><small>The answer is {quiz.options[quiz.answer]}.</small></div>)}</div>}{result.flashcards?.length>0&&<div className="result-section"><h3>Flashcards</h3><div className="flash-grid">{result.flashcards.map((card,index)=><button type="button" className="flash-card" key={index} onClick={()=>setRevealed({...revealed,[index]:!revealed[index]})}><span>{revealed[index]?'BACK':'FRONT'}</span><b>{revealed[index]?card.back:card.front}</b><small>Click to flip</small></button>)}</div></div>}</section>}</div>
}
const interviewTopics=['Java','Python','JavaScript','C','C++','HTML','CSS','React','Node.js','SQL','MongoDB','Data Structures','Algorithms','Computer Networks','Operating Systems','DBMS','aptitude','logical reasoning','HR/behavioral'];
const INTERVIEW_QUESTION_COUNT=15;
function Interview() {
 const [role,setRole]=useState('Software Engineer'); const [topic,setTopic]=useState('JavaScript'); const [difficulty,setDifficulty]=useState('Intermediate'); const [session,setSession]=useState(null); const [index,setIndex]=useState(0); const [answers,setAnswers]=useState([]); const [draft,setDraft]=useState(''); const [report,setReport]=useState(null); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [voiceMode,setVoiceMode]=useState(false); const [voiceFeedback,setVoiceFeedback]=useState(null); const [answerFeedback,setAnswerFeedback]=useState(null); const [feedbackByIndex,setFeedbackByIndex]=useState({}); const [listening,setListening]=useState(false); const [interim,setInterim]=useState(''); const recognitionRef=useRef(null); const navigationLock=useRef(false); const currentQuestion=session?.questions?.[index]||null;
 function speak(text){try{if(!window.speechSynthesis||typeof window.SpeechSynthesisUtterance!=='function'){setError('Spoken audio is unavailable in this browser. You can continue with the written question.');return;}window.speechSynthesis.cancel();const utterance=new window.SpeechSynthesisUtterance(text);utterance.lang='en-US';const english=window.speechSynthesis.getVoices().find(voice=>voice.lang?.toLowerCase().startsWith('en'));if(english)utterance.voice=english;window.speechSynthesis.speak(utterance);}catch{setError('Could not play speech in this browser. You can continue with the written question.');}}
 useEffect(()=>()=>{recognitionRef.current?.stop();window.speechSynthesis?.cancel();},[]);
 async function start(voice=false){setError('');setBusy(true);try{const r=await api.post('/interviews/start',{role,topic,difficulty,voiceMode:voice});if(!Array.isArray(r.data?.questions)||r.data.questions.length!==INTERVIEW_QUESTION_COUNT||r.data.questions.some(item=>!item?.question))throw new Error('The interview service returned an incomplete question set. Please retry.');setSession(r.data);setAnswers(Array(INTERVIEW_QUESTION_COUNT).fill(''));setIndex(0);setReport(null);setDraft('');setVoiceMode(voice);setVoiceFeedback(null);setAnswerFeedback(null);setFeedbackByIndex({});if(voice)speak(r.data.questions[0].question);}catch(err){setError(err.response?.data?.error||'Could not start an interview.');}finally{setBusy(false);}}
 function handleStart(event){event.preventDefault();start(false);}
 function startListening(){setError('');setInterim('');const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){setError('English speech recognition is not supported in this browser. Type your answer or use the latest Chrome or Edge.');return;}try{const recognition=new Recognition();recognition.lang='en-US';recognition.interimResults=true;recognition.continuous=false;recognition.onstart=()=>{setListening(true);setError('');};recognition.onresult=event=>{let finalText='';let liveText='';for(let i=event.resultIndex;i<event.results.length;i++){const text=event.results[i][0].transcript;if(event.results[i].isFinal)finalText+=text;else liveText+=text;}if(finalText.trim())setDraft(previous=>previous+(previous?' ':'')+finalText.trim());setInterim(liveText);};recognition.onerror=event=>{const messages={'not-allowed':'Microphone access was denied. Allow microphone access for this site and try again.','service-not-allowed':'The browser speech service is unavailable. Type your answer instead.','audio-capture':'No microphone was detected. Connect or enable a microphone.','no-speech':'No speech was detected. Try again a little closer to the microphone.','network':'The browser speech service could not connect. Check your connection or type your answer.'};setError(messages[event.error]||('Speech recognition stopped ('+event.error+'). You can still type your answer.'));};recognition.onend=()=>{setListening(false);setInterim('');recognitionRef.current=null;};recognitionRef.current=recognition;recognition.start();}catch{setListening(false);setError('Could not start the microphone. Check site permissions and try again.');}}
 function stopListening(){recognitionRef.current?.stop();setListening(false);}
 async function evaluateCurrent(){if(!draft.trim()){setError('Add or speak an answer before continuing.');return;}setError('');setBusy(true);try{const endpoint=voiceMode?'voice-answer':'answer';const response=await api.post('/interviews/'+session._id+'/'+endpoint,{index,answer:draft});const updated=[...answers];updated[index]=draft.trim();setAnswers(updated);const feedback={...response.data.evaluation,correctAnswer:response.data.correctAnswer,explanation:response.data.explanation};setFeedbackByIndex(previous=>({...previous,[index]:feedback}));if(voiceMode){setVoiceFeedback(feedback);speak(feedback.feedback+' '+feedback.strength+' '+feedback.improvement+' Reference answer: '+feedback.correctAnswer);}else setAnswerFeedback(feedback);}catch(err){setError(err.response?.data?.error||'Could not evaluate this answer.');}finally{setBusy(false);}}
 async function submit(all){if(!session?._id||!Array.isArray(all)||all.length!==session.questions.length||all.some(answer=>!String(answer||'').trim())){setError('Complete all questions before opening the report. Your answers are still available on this page.');return;}setBusy(true);setError('');try{const r=await api.post('/interviews/'+session._id+'/submit',{answers:all});if(!r.data?.report||!Array.isArray(r.data.report.questionEvaluations))throw new Error('The report response was incomplete. Your answers remain saved; retry the report.');setReport(r.data.report);window.speechSynthesis?.cancel();}catch(err){setError(err.response?.data?.error||err.message||'Could not generate your report. Your answers are still available on this page.');}finally{setBusy(false);}}
 async function advance(){if(navigationLock.current||busy)return;navigationLock.current=true;try{if(!session?._id||!currentQuestion){setError('This interview question is unavailable. Start a new session to continue.');return;}const updated=Array(session.questions.length).fill('').map((_,i)=>answers[i]||'');updated[index]=draft.trim();if(!updated[index]){setError('Add an answer before continuing.');return;}if(index===session.questions.length-1){await submit(updated);return;}const nextIndex=index+1;const nextQuestion=session.questions[nextIndex];if(!nextQuestion?.question){setError('The next question is missing. Your current answer has been kept; start a new session to recover.');return;}setAnswers(updated);setIndex(nextIndex);setDraft(updated[nextIndex]);setVoiceFeedback(feedbackByIndex[nextIndex]||null);setAnswerFeedback(feedbackByIndex[nextIndex]||null);setError('');if(voiceMode)speak(nextQuestion.question);}catch(err){console.error('Interview navigation failed:',err);setError('Could not open the next question. Your current answer has been kept; try again or start a new session.');}finally{navigationLock.current=false;}}
 function previous(){if(index===0||!session?.questions?.[index-1])return;const updated=Array(session.questions.length).fill('').map((_,i)=>answers[i]||'');updated[index]=draft;setAnswers(updated);const previousIndex=index-1;setIndex(previousIndex);setDraft(updated[previousIndex]||'');setVoiceFeedback(feedbackByIndex[previousIndex]||null);setAnswerFeedback(feedbackByIndex[previousIndex]||null);setError('');if(voiceMode)speak(session.questions[previousIndex].question);}
 function newSession(){recognitionRef.current?.stop();window.speechSynthesis?.cancel();setSession(null);setIndex(0);setAnswers([]);setDraft('');setReport(null);setVoiceFeedback(null);setAnswerFeedback(null);setFeedbackByIndex({});setError('');setBusy(false);}
 if(session&&(!Array.isArray(session.questions)||session.questions.length!==INTERVIEW_QUESTION_COUNT))return <div className="page-content"><PageHeader eyebrow="MOCK INTERVIEW" title="This session cannot continue." subtitle="The server did not return all fifteen interview questions." action={<Button secondary onClick={newSession}>Start a new session</Button>}/><div className="error-banner" role="alert">Your saved answers are not deleted. Start a fresh session or reload to reconnect to the API.</div></div>;
 if(session&&!currentQuestion&&!report)return <div className="page-content"><PageHeader eyebrow="MOCK INTERVIEW" title="Question unavailable." subtitle="Your session is still here; recover without leaving a blank page." action={<Button secondary onClick={newSession}>Start a new session</Button>}/><div className="error-banner" role="alert">Could not load question {index+1}. Your answers remain saved for this session.</div></div>;
 if(report)return <div className="page-content"><PageHeader eyebrow="INTERVIEW REPORT" title="A strong start." subtitle={topic+' · '+role+' · '+difficulty} action={<Button secondary onClick={newSession}>New session</Button>}/><div className="report-top"><div className="score-panel"><div className="eyebrow">{report.scoreStatus==='needs-manual-review'?'NEEDS MANUAL REVIEW':'OVERALL SCORE · REFERENCE RUBRIC'}</div><div className="score-value">{report.overallScore??'—'}<span>{report.overallScore==null?'':'%'}</span></div><div className="score-bar"><i style={{width:(report.overallScore??0)+'%'}}/></div><small>{report.evaluationNote}</small><small className="report-formula">{report.scoreFormula}</small></div><div className="score-breakdown">{Object.entries(report.scores||{}).filter(([,v])=>v!==null).map(([k,v])=><div key={k}><span>{({correctness:'Correctness',relevance:'Relevance',completeness:'Completeness',problemSolving:'Problem solving',communication:'Communication'})[k]||k}</span><b>{v}%</b><div className="mini-track"><i style={{width:v+'%'}}/></div></div>)}</div></div><div className="report-columns"><section className="panel report-panel"><h2><Check size={17}/> What went well</h2>{(report.strengths||[]).length?(report.strengths||[]).map((x,i)=><p className="report-item" key={i}>{x}</p>):<p className="report-item">No strengths were scored automatically.</p>}</section><section className="panel report-panel"><h2><Target size={17}/> Focus for next time</h2>{(report.weaknesses||[]).length?(report.weaknesses||[]).map((x,i)=><p className="report-item" key={i}>{x}</p>):<p className="report-item">No missing concepts were identified in the evaluated answers.</p>}</section></div><section className="panel report-panel"><h2><Brain size={17}/> Topics to revisit</h2><div className="topic-chips">{(report.topicsToRevise||[]).map((x,i)=><span key={i}>{x}</span>)}</div></section><section className="panel report-panel"><h2><Sparkles size={17}/> Question answer review</h2>{(report.questionEvaluations||[]).map((item,i)=><div className="improved" key={i}><span>0{i+1}</span><div><b>{item.question}</b><p><strong>Your answer:</strong> {item.answer||"No answer"}</p><p><strong>Status:</strong> {item.status==='needs-manual-review'?'Needs manual review':item.score+'% · Evaluated'}</p>{item.missingConcepts?.length>0&&<p><strong>Missing concepts:</strong> {item.missingConcepts.join('; ')}</p>}<p><strong>Reference:</strong> {item.referenceAnswer}</p><p><strong>Explanation:</strong> {item.explanation}</p></div></div>)}</section></div>;
 return <div className="page-content"><PageHeader eyebrow="MOCK INTERVIEW" title="Practice before it counts." subtitle="Choose a topic, then rehearse one question at a time."/>
 {!session?<div className="interview-start-grid"><form className="panel start-panel" onSubmit={handleStart}><div className="panel-heading"><div><h2>Set up your session</h2><p>Fifteen locally prepared questions matched to your topic and level.</p></div><div className="session-symbol"><Mic2 size={18}/></div></div><label className="field-label" htmlFor="interview-role">JOB ROLE</label><input id="interview-role" className="text-input" value={role} onChange={event=>setRole(event.target.value)} maxLength={80} required/><label className="field-label" htmlFor="interview-topic">TOPIC / CATEGORY</label><select id="interview-topic" className="text-input source-select" value={topic} onChange={event=>setTopic(event.target.value)}>{interviewTopics.map(value=><option key={value}>{value}</option>)}</select><label className="field-label">DIFFICULTY</label><div className="choice-row">{['Beginner','Intermediate','Advanced'].map(value=><button type="button" className={difficulty===value?'choice selected':'choice'} onClick={()=>setDifficulty(value)} key={value}>{value}</button>)}</div><div className="interview-start-actions"><button className="button" type="submit" disabled={busy}>{busy?<><span className="spinner"/> Preparing…</>:<>Begin practice <ArrowUpRight size={15}/></>}</button><button className="button secondary" type="button" disabled={busy} onClick={()=>start(true)}><Mic size={15}/> Start Voice Practice</button></div>{error&&<div className="error-banner" role="alert">{error}</div>}</form><div className="interview-aside"><div className="eyebrow">A LITTLE PREP GOES A LONG WAY</div><h2>Think out loud.<br/>Find your rhythm.</h2><p>Fifteen {topic} questions at {difficulty.toLowerCase()} level, with reference answers and a saved report.</p><div className="interview-details"><span><Clock3 size={15}/> About 10 minutes</span><span><CircleHelp size={15}/> 9 topic · 3 scenario · 3 behavioral</span><span><FileText size={15}/> Local feedback after each answer</span></div></div></div>
 :<div className="question-layout"><section className="panel question-panel"><div className="question-top"><span>{topic.toUpperCase()} · QUESTION {String(index+1).padStart(2,'0')} <i>/ {String(session.questions.length).padStart(2,'0')}</i></span><span className="question-type">{currentQuestion.type}</span></div><div className="question-progress">{session.questions.map((_,i)=><i className={i<index?'done':i===index?'current':''} key={i}/>)}</div><div className="voice-question"><h2>{currentQuestion.question}</h2><button type="button" className="quiet-action" onClick={()=>speak(currentQuestion.question)} aria-label="Hear question again" title="Hear question again"><Volume2 size={14}/> Hear again</button></div>{voiceMode&&<div className="voice-consent-note">English speech recognition uses your browser’s microphone service. PrepAI saves the editable transcript, not audio.</div>}<label className="field-label" htmlFor="interview-answer">YOUR ANSWER{voiceMode?' · EDIT THE TRANSCRIPT BEFORE SENDING':''}</label><textarea id="interview-answer" className="answer-input" value={draft} onChange={event=>{setDraft(event.target.value);setVoiceFeedback(null);setAnswerFeedback(null);setFeedbackByIndex(previous=>({...previous,[index]:null}));}} placeholder={voiceMode?'Start the microphone or type your answer…':'Take a moment to organize your thoughts…'} maxLength={2400}/>{interim&&<div className="speech-interim" aria-live="polite">Hearing: {interim}</div>}{voiceMode&&<div className="voice-actions"><button className="button secondary" type="button" disabled={busy} onClick={listening?stopListening:startListening}>{listening?<><span className="listening-dot"/> Stop listening</>:<><Mic size={15}/> Start microphone</>}</button>{listening&&<span className="status-note">Listening in English…</span>}</div>}<div className="form-foot"><span>{draft.length} / 2,400</span>{!voiceFeedback&&!answerFeedback?<button className="button" type="button" disabled={busy||listening} onClick={evaluateCurrent}>{busy?<><span className="spinner"/> Evaluating…</>:<>Evaluate answer <ArrowUpRight size={15}/></>}</button>:<button className="button" type="button" disabled={busy} onClick={advance}>{index===session.questions.length-1?<>Finish session <Check size={15}/></>:<>Next question <ChevronRight size={15}/></>}</button>}</div>{error&&<div className="error-banner" role="alert">{error}</div>}{(voiceFeedback||answerFeedback)&&(()=>{const feedback=voiceFeedback||answerFeedback;return <div className="voice-feedback" role="status"><div className="voice-feedback-heading"><b>{feedback.status==='needs-manual-review'?'Needs manual review':'Answer evaluation'}</b>{voiceMode&&<button className="quiet-action" type="button" onClick={()=>speak(feedback.feedback+' Reference answer: '+feedback.correctAnswer)}><Volume2 size={14}/> Listen to feedback</button>}</div><div className="voice-score-grid">{Object.entries(feedback.scores||{}).filter(([,value])=>value!==null).map(([key,value])=><div key={key}><span>{({correctness:'Correctness',relevance:'Relevance',completeness:'Completeness',grammar:'Grammar',clarity:'Clarity'})[key]||key}</span><b>{value}%</b></div>)}</div><p>{feedback.feedback}</p>{feedback.strength&&<p><strong>Strength:</strong> {feedback.strength}</p>}<p><strong>Improve:</strong> {feedback.improvement}</p>{feedback.missingConcepts?.length>0&&<p><strong>Missing concepts:</strong> {feedback.missingConcepts.join('; ')}</p>}<p><strong>Reference answer:</strong> {feedback.correctAnswer}</p><p><strong>Explanation:</strong> {feedback.explanation}</p><small>{feedback.note}</small></div>;})()}</section><aside className="question-aside"><div className="aside-note"><div className="aside-note-icon"><Sparkles size={17}/></div><h3>Take your time</h3><p>There’s no clock here. Clear thinking beats a quick answer every time.</p></div>{index>0&&<button className="quiet-action" type="button" onClick={previous}><ChevronLeft size={14}/> Previous question</button>}<button className="quiet-action" type="button" onClick={()=>{setDraft('');setInterim('');setError('');}}><RotateCcw size={14}/> Clear this answer</button></aside></div>}
 </div>;
}
function Progress() {
 const navigate=useNavigate();
 const [data,setData]=useState({interviews:[],learnings:[],weakTopics:[]});
 useEffect(()=>{api.get('/progress').then(r=>setData(r.data)).catch(()=>{});},[]);
 return <div className="page-content"><PageHeader eyebrow="YOUR PROGRESS" title="See how far you’ve come." subtitle="A little reflection makes every next session more useful."/><div className="progress-summary"><Stat label="Sessions completed" value={data.interviews.length} delta="Interview reports" icon={Mic2}/><Stat label="Study packs" value={data.learnings.length} delta="Learning sessions saved" icon={BookOpen} accent="mint"/><Stat label="Recent average" value={data.interviews.length?Math.round(data.interviews.slice(0,5).reduce((s,x)=>s+(x.report?.overallScore||0),0)/Math.min(5,data.interviews.length))+'%':'—'} delta="Across your last 5 reports" icon={Target} accent="purple"/></div><div className="dashboard-columns"><section className="panel recent-panel"><div className="panel-heading"><div><h2>Interview history</h2><p>Your completed practice sessions</p></div></div>{data.interviews.length?data.interviews.map((x,i)=><div className="activity-row" key={x._id||i}><div className="activity-icon violet"><Mic2 size={16}/></div><div className="activity-name"><b>{x.role}</b><span>{x.topic||"General"} · {x.difficulty} · {new Date(x.createdAt).toLocaleDateString()}</span></div><div className="activity-meta">{x.report?.overallScore||'—'}% score</div></div>):<div className="empty-compact">Your completed interviews will appear here.</div>}</section><section className="panel actions-panel"><div className="panel-heading"><div><h2>Topics to revisit</h2><p>Based on your interview reports</p></div></div>{data.weakTopics.length?data.weakTopics.map((x,i)=><div className="topic-row" key={i}><span>{x.topic}</span><b>{x.count}×</b></div>):<div className="empty-compact">Complete a practice session to surface revision topics.</div>}</section></div><section className="panel learning-history"><div className="panel-heading"><div><h2>Learning sessions</h2><p>Continue a topic guide or transcript study</p></div></div>{data.learnings.length?data.learnings.map((item,index)=><div className="activity-row" key={item._id||index}><div className="activity-icon cyan"><BookOpen size={16}/></div><div className="activity-name"><b>{item.title}</b><span>{new Date(item.createdAt).toLocaleDateString()} · {item.finalizedAt?'Finalized':'In progress'}</span></div><button className="button secondary" type="button" onClick={()=>navigate('/learn?session='+item._id)}>Open session</button></div>):<div className="empty-compact">Your topic guides will appear here after you create one.</div>}</section></div>
}

function AuthPage({ mode, onAuthenticated }) {
 const [name,setName]=useState(''); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const navigate=useNavigate(); const signup=mode==='signup';
 const [theme,setTheme]=useState(()=>localStorage.getItem('prepai-theme')==='light'?'light':'dark');
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('prepai-theme',theme);},[theme]);
 async function submit(event){event.preventDefault();setError('');setBusy(true);try{const response=await api.post(`/auth/${signup?'signup':'login'}`,{name,email,password});onAuthenticated(response.data.user);navigate('/');}catch(err){setError(err.response?.data?.error||'Could not sign in. Check the database connection and try again.');}finally{setBusy(false);}}
 async function startDemo(){setError('');setBusy(true);try{const response=await api.post('/auth/demo');onAuthenticated(response.data.user);navigate('/');}catch(err){setError(err.response?.data?.error||'Could not start the demo. Check the database connection and try again.');}finally{setBusy(false);}}
 return <div className="auth-shell"><button className="icon-button auth-theme-toggle" onClick={()=>setTheme(theme==='dark'?'light':'dark')} aria-label={theme==='dark'?'Switch to light theme':'Switch to dark theme'}>{theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}</button><section className="auth-card"><NavLink className="auth-brand" to="/"><span className="brand-mark">p</span> prepai<span>.</span></NavLink><div className="eyebrow">YOUR PREPARATION WORKSPACE</div><h1>{signup?'Create your account':'Welcome back'}</h1><p>{signup?'Save your study packs and interview progress in one private workspace.':'Sign in to continue your learning and interview practice.'}</p><form onSubmit={submit}>{signup&&<><label className="field-label" htmlFor="auth-name">YOUR NAME</label><input id="auth-name" className="text-input" autoComplete="name" value={name} onChange={event=>setName(event.target.value)} minLength={2} maxLength={80} required/></>}<label className="field-label" htmlFor="auth-email">EMAIL</label><input id="auth-email" className="text-input" type="email" autoComplete="email" value={email} onChange={event=>setEmail(event.target.value)} required/><label className="field-label" htmlFor="auth-password">PASSWORD</label><input id="auth-password" className="text-input" type="password" autoComplete={signup?'new-password':'current-password'} value={password} onChange={event=>setPassword(event.target.value)} minLength={signup?8:1} maxLength={128} required/>{error&&<div className="error-banner" role="alert">{error}</div>}<button className="button auth-submit" disabled={busy}>{busy?<><span className="spinner"/> Working…</>:signup?'Create account':'Sign in'}</button></form>{!signup&&<div className="demo-entry"><button className="button secondary" type="button" disabled={busy} onClick={startDemo}><Play size={15}/> Start guided demo</button><small>Sample account with sample data; no password required.</small></div>}<p className="auth-switch">{signup?'Already have an account?':'New to PrepAI?'} <NavLink to={signup?'/login':'/signup'}>{signup?'Sign in':'Create an account'}</NavLink></p><small className="auth-note">Your password is encrypted before storage and is never sent to an AI provider.</small></section></div>;
}

function ProfileForm({ user, onSaved, setup=false, onLogout }) {
 const [name,setName]=useState(user.name||''); const [phone,setPhone]=useState(user.phone||''); const [collegeName,setCollegeName]=useState(user.collegeName||''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [saved,setSaved]=useState(false);
 async function submit(event){event.preventDefault();setError('');setSaved(false);setBusy(true);try{const response=await api.put('/profile',{name,phone,collegeName});onSaved(response.data.user);setSaved(true);}catch(err){setError(err.response?.data?.error||'Could not save your profile.');}finally{setBusy(false);}}
 return <div className={setup?'profile-setup-shell':'profile-settings-wrap'}>{setup&&<><div className="profile-setup-brand"><span className="brand-mark">p</span> prepai<span>.</span></div><button type="button" className="quiet-action profile-signout" onClick={onLogout}>Sign out</button></>}<form className={setup?'profile-setup-card':'panel settings-panel profile-panel'} onSubmit={submit}><div className="panel-heading"><div><div className="eyebrow">{setup?'FIRST LOGIN':'YOUR ACCOUNT'}</div><h2><UserRound size={17}/>{setup?'Complete your profile':'Profile details'}</h2><p>{setup?'Add your details to personalize your preparation workspace.':'Update the profile details saved to your account.'}</p></div></div><label className="field-label" htmlFor="profile-name">FULL NAME</label><input id="profile-name" className="text-input" value={name} onChange={event=>setName(event.target.value)} minLength={2} maxLength={80} autoComplete="name" required/><label className="field-label" htmlFor="profile-email">EMAIL</label><input id="profile-email" className="text-input" type="email" value={user.email} readOnly aria-readonly="true"/><small className="form-hint">Email is your sign-in ID and cannot be changed here.</small><label className="field-label" htmlFor="profile-phone">PHONE NUMBER</label><input id="profile-phone" className="text-input" type="tel" value={phone} onChange={event=>setPhone(event.target.value)} pattern="[+()0-9 .-]{7,24}" autoComplete="tel" placeholder="+1 555 0100" required/><label className="field-label" htmlFor="profile-college">COLLEGE NAME</label><input id="profile-college" className="text-input" value={collegeName} onChange={event=>setCollegeName(event.target.value)} minLength={2} maxLength={120} autoComplete="organization" required/>{error&&<div className="error-banner" role="alert">{error}</div>}<div className="settings-actions"><button className="button" disabled={busy}>{busy?'Saving…':setup?'Save and continue':'Save profile'}</button>{saved&&!setup&&<span className="saved-message" role="status">Profile saved.</span>}</div></form>{setup&&<small className="auth-note">Your profile details stay with your PrepAI account.</small>}</div>;
}

function SettingsPage({ user, onProfileSaved }) {
 const [language,setLanguage]=useState('English'); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [saved,setSaved]=useState(false);
 useEffect(()=>{api.get('/settings').then(response=>setLanguage(response.data.settings.outputLanguage||'English')).catch(err=>setError(err.response?.data?.error||'Could not load settings.'));},[]);
 async function save(event){event.preventDefault();setBusy(true);setError('');setSaved(false);try{const response=await api.put('/settings',{outputLanguage:language});setLanguage(response.data.settings.outputLanguage);setSaved(true);}catch(err){setError(err.response?.data?.error||'Could not save settings.');}finally{setBusy(false);}}
 return <div className="page-content"><PageHeader eyebrow="PREFERENCES" title="Settings" subtitle="Manage your profile and learning preferences."/><ProfileForm user={user} onSaved={onProfileSaved}/><form className="panel settings-panel" onSubmit={save}><div className="panel-heading"><div><h2><Languages size={16}/> Language preference</h2><p>Saved to your account and used as the default for new sessions.</p></div></div><label className="field-label" htmlFor="settings-language">OUTPUT LANGUAGE</label><select id="settings-language" className="text-input source-select" value={language} onChange={event=>{setLanguage(event.target.value);setSaved(false);}}>{['English','Spanish','Hindi','French','German','Japanese','Portuguese','Chinese','Korean','Arabic','Russian','Italian'].map(value=><option key={value}>{value}</option>)}</select><div className="settings-actions"><button className="button" disabled={busy}>{busy?'Saving…':'Save preferences'}</button>{saved&&<span className="saved-message" role="status">Preferences saved.</span>}</div>{error&&<div className="error-banner" role="alert">{error}</div>}<p className="settings-note">Video Learning works locally without an AI key. Paste captions or a transcript for source-based notes; YouTube links and media files are not fetched or transcribed. Output uses the transcript’s detected language.</p></form></div>;
}

export default function App(){
 const [user,setUser]=useState(null); const [checkingAuth,setCheckingAuth]=useState(true); const navigate=useNavigate(); const location=useLocation();
 useEffect(()=>{let active=true;api.get('/auth/me').then(response=>{if(active)setUser(response.data.user);}).catch(()=>{if(active)setUser(null);}).finally(()=>{if(active)setCheckingAuth(false);});return()=>{active=false;};},[]);
 async function logout(){try{await api.post('/auth/logout');}catch(error){console.error('Logout request failed:',error);}finally{setUser(null);navigate('/login');}}
 if(checkingAuth)return <div className="loading-page"><span className="spinner"/> Preparing your workspace…</div>;
 if(!user)return <Routes><Route path="/signup" element={<AuthPage key="signup" mode="signup" onAuthenticated={setUser}/>}/><Route path="*" element={<AuthPage key={location.pathname==='/signup'?'signup':'login'} mode="login" onAuthenticated={setUser}/>}/></Routes>;
 if(!user.profileComplete)return <ProfileForm user={user} onSaved={setUser} onLogout={logout} setup/>;
 return <Shell user={user} onLogout={logout}><Routes><Route path="/" element={<Dashboard user={user}/>}/><Route path="/learn" element={<Learn/>}/><Route path="/interview" element={<Interview/>}/><Route path="/progress" element={<Progress/>}/><Route path="/settings" element={<SettingsPage user={user} onProfileSaved={setUser}/>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes></Shell>;
}

